# --------------------------------------------------------------------------- question helpers
def mc(q, options, answer, explain, stars=None, obj=""):
    d = dict(type="mc", obj=obj, q=q, options=options, answer=answer, explain=explain)
    if stars: d["stars"] = stars
    return d


def tf(q, answer, explain, stars=None, obj=""):
    d = dict(type="tf", obj=obj, q=q, answer=answer, explain=explain)
    if stars: d["stars"] = stars
    return d


def num(q, answer, explain, unit="", tolerance=0, stars=None, obj=""):
    d = dict(type="num", obj=obj, q=q, answer=answer, tolerance=tolerance, unit=unit, explain=explain)
    if stars: d["stars"] = stars
    return d


def order(q, items, explain, stars=None, obj=""):
    d = dict(type="order", obj=obj, q=q, items=items, explain=explain)
    if stars: d["stars"] = stars
    return d


def match(q, pairs, explain, stars=None, obj=""):
    d = dict(type="match", obj=obj, q=q, pairs=pairs, explain=explain)
    if stars: d["stars"] = stars
    return d


def openq(q, solution, hint=None, stars=None, obj=""):
    d = dict(type="open", obj=obj, q=q, solution=solution)
    if hint: d["hint"] = hint
    if stars: d["stars"] = stars
    return d


